INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('fc85340f-bd80-5bfe-a98c-fe13d7f513d3','TEXT','The Paper Kite Map','Arun liked helping at the open oval, especially when there was a small job that nobody had planned. One Wednesday, Arun noticed the kite map was not working as expected. The problem seemed simple at first, but the usual quick fix did not help. Arun decided to stop and look carefully instead of rushing.
