INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('0ff6260e-ff0e-5674-a62b-3bfef4f8be18','TEXT','The Museum Window','Noah liked helping at the local museum, especially when there was a small job that nobody had planned. One Friday, Noah noticed the old window frame was not working as expected. The problem seemed simple at first, but the usual quick fix did not help. Noah decided to stop and look carefully instead of rushing.
INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('537c83dd-9450-5f81-af66-c186ec0e58e7','TEXT','The Tiny Ferry — A Different Day','Ruby liked helping at the river workshop, especially when there was a small job that nobody had planned. One Friday, Ruby noticed the model ferry was not working as expected. The problem seemed simple at first, but the usual quick fix did not help. Ruby decided to stop and look carefully instead of rushing.
