INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('de86f000-dd27-51ae-aea3-450669f8f663','TEXT','The Tiny Ferry','Ruby liked helping at the river workshop, especially when there was a small job that nobody had planned. One Saturday, Ruby noticed the model ferry was not working as expected. The problem seemed simple at first, but the usual quick fix did not help. Ruby decided to stop and look carefully instead of rushing.
INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('24cf13ac-8c53-5cc0-aba4-cc9eeba259ff','TEXT','The Bicycle Bell Project — A Different Day','Luca liked helping at the bike path, especially when there was a small job that nobody had planned. One Thursday, Luca noticed the bicycle bell was not working as expected. The problem seemed simple at first, but the usual quick fix did not help. Luca decided to stop and look carefully instead of rushing.
INSERT INTO testlets (id,section_id,stimulus_id,title,testlet_order,is_branching_node,navigation_locked,calculator_allowed,instructions) VALUES ('47332000-9b9a-5c17-9986-2d0ef53b205c','e90184f5-5754-53f8-9540-032da62d52b6','de86f000-dd27-51ae-aea3-450669f8f663','C',4,TRUE,FALSE,NULL,'Complete this C testlet. Answer every question before continuing.');
