INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('9a463691-bf8a-50af-8014-5e40d16a0ec3','TEXT','The Bicycle Bell Project','Luca liked helping at the bike path, especially when there was a small job that nobody had planned. One Tuesday, Luca noticed the bicycle bell was not working as expected. The problem seemed simple at first, but the usual quick fix did not help. Luca decided to stop and look carefully instead of rushing.
INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('6708fbc1-2578-52ff-81cb-59583a50d8e6','TEXT','The Orange Tree Calendar — A Different Day','Zoe liked helping at the school orchard, especially when there was a small job that nobody had planned. One Friday, Zoe noticed the fruit calendar was not working as expected. The problem seemed simple at first, but the usual quick fix did not help. Zoe decided to stop and look carefully instead of rushing.
