INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('05167356-1351-5e22-b042-8463b1915c85','TEXT','The Repaired Book','Amara liked helping at the library corner, especially when there was a small job that nobody had planned. One Friday, Amara noticed the repair kit was not working as expected. The problem seemed simple at first, but the usual quick fix did not help. Amara decided to stop and look carefully instead of rushing.
INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('fe54306e-70b4-55f8-a7db-d95513aaae9f','TEXT','The Windy Sculpture — A Different Day','Kai liked helping at the community hall, especially when there was a small job that nobody had planned. One Tuesday, Kai noticed the reed sculpture was not working as expected. The problem seemed simple at first, but the usual quick fix did not help. Kai decided to stop and look carefully instead of rushing.
